// Verbatim statutory text sourced from India Code (indiacode.nic.in), the official government
// digital repository. This mirrors legal-platform-backend/data/law-library-raw/ — see those
// files for the SOURCE url of each Act. Never paraphrase or summarize text added here.

export interface ActSection {
  sectionNo: string;
  heading: string;
  text: string;
  /** Groups sections under a labelled part for large Acts (e.g. the Constitution's Parts).
   * Sections without this render as a flat list, as before. */
  part?: string;
}

export type ActJurisdiction = { type: 'central' } | { type: 'state'; state: string };

export interface Act {
  id: string;
  shortTitle: string;
  year: number;
  actNumber: string;
  sourceUrl: string;
  sections: ActSection[];
  jurisdiction: ActJurisdiction;
  /** Defaults to 'act' when omitted. 'rules' marks delegated/subordinate legislation (procedural
   * Rules notified under an Act, rather than an Act passed by the legislature itself) — the UI
   * labels these distinctly so a user doesn't mistake a Rule for a section of the parent Act. */
  instrumentType?: 'act' | 'rules';
  /** Marks a repealed predecessor Act (e.g. the Code of Criminal Procedure, 1973, superseded by
   * the Bharatiya Nagarik Suraksha Sanhita, 2023) kept in the Library for historical reference and
   * section-correspondence lookups only — never the current law. The UI shows a prominent warning
   * banner and a link to `supersededByActId` whenever this is set, so a user can't mistake a
   * repealed section for something still in force. */
  status?: 'repealed';
  /** The `Act.id` of the current law that replaced this one — required whenever `status` is set. */
  supersededByActId?: string;
}

